from urllib.parse import parse_qsl, urlsplit, urlunsplit


def apply_rewrite_rules(rules, urls):
    """Apply the first matching rewrite rule to each URL."""

    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            domain = match_value[2:]
            # Must be a subdomain, not the domain itself.
            return host != domain and host.endswith("." + domain)

        return host == match_value

    def replace_host(netloc, new_host):
        """Replace only the hostname, preserving userinfo and port."""
        userinfo = ""
        hostport = netloc

        if "@" in hostport:
            userinfo, hostport = hostport.rsplit("@", 1)
            userinfo += "@"

        port = ""

        if hostport.startswith("["):  # IPv6 host
            closing_bracket = hostport.find("]")
            if closing_bracket != -1:
                port = hostport[closing_bracket + 1:]
        else:
            colon = hostport.rfind(":")
            if colon != -1 and hostport[colon + 1:].isdigit():
                port = hostport[colon:]

        # Bracket an IPv6 replacement host when necessary.
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        return userinfo + new_host + port

    results = []

    for original_url in urls:
        try:
            parsed = urlsplit(original_url)
        except ValueError:
            results.append(original_url)
            continue

        matched_rule = None

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]

            if match_type == "path_prefix":
                matches = parsed.path.startswith(match_value)

            elif match_type == "host":
                matches = host_matches(parsed.hostname, match_value)

            elif match_type == "query_param":
                query_names = {
                    name for name, _ in parse_qsl(
                        parsed.query,
                        keep_blank_values=True
                    )
                }
                matches = match_value in query_names

            else:
                raise ValueError(f"Unsupported match_type: {match_type}")

            if matches:
                matched_rule = rule
                break

        if matched_rule is None:
            results.append(original_url)
            continue

        action = matched_rule["action"]

        if action == "block":
            results.append(None)
            continue

        action_value = matched_rule.get("action_value")

        if action == "strip_prefix":
            path = parsed.path
            if path.startswith(action_value):
                path = path[len(action_value):]
            if not path:
                path = "/"

            rewritten = parsed._replace(path=path)

        elif action == "redirect_host":
            new_netloc = replace_host(parsed.netloc, action_value)
            rewritten = parsed._replace(netloc=new_netloc)

        elif action == "add_query_param":
            query = parsed.query
            if query:
                query += "&" + action_value
            else:
                query = action_value

            rewritten = parsed._replace(query=query)

        else:
            raise ValueError(f"Unsupported action: {action}")

        results.append(urlunsplit(rewritten))

    return results
